#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int a, b;
    int used;
} Edge;

typedef struct {
    int *v;
    int sz, cap;
} Vec;

static void vec_push(Vec *vec, int x) {
    if (vec->sz == vec->cap) {
        vec->cap = vec->cap ? vec->cap * 2 : 4;
        vec->v = (int*)realloc(vec->v, vec->cap * sizeof(int));
    }
    vec->v[vec->sz++] = x;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    Edge *edges = (Edge*)malloc(m * sizeof(Edge));
    Vec *adj = (Vec*)calloc(n + 1, sizeof(Vec)); /* vertices are 1..n */

    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        edges[i].a = u;
        edges[i].b = v;
        edges[i].used = 0;
        vec_push(&adj[u], i);
        vec_push(&adj[v], i);
    }

    /* Euler formula for connected planar graph:
       F = E - V + 2
       number of interior rooms = F - 1 = E - V + 1
    */
    int maxFaces = m - n + 2;
    if (maxFaces < 1) maxFaces = 1;

    int **faceVerts = (int**)malloc(maxFaces * sizeof(int*));
    int *faceSz = (int*)calloc(maxFaces, sizeof(int));
    int faceCnt = 0;

    int *stack = (int*)malloc((m + 5) * sizeof(int));

    /* Find all bounded faces by peeling cycles from the cactus-like wall graph. */
    for (int s = 1; s <= n; ++s) {
        if (adj[s].sz < 2) continue;
        for (int ii = 0; ii < adj[s].sz; ++ii) {
            int eidx = adj[s].v[ii];
            if (edges[eidx].used) continue;

            int top = 0;
            int cur = s;
            int prevEdge = -1;

            while (1) {
                stack[top++] = cur;

                int nextEdge = -1;
                for (int j = 0; j < adj[cur].sz; ++j) {
                    int id = adj[cur].v[j];
                    if (id != prevEdge && !edges[id].used) {
                        nextEdge = id;
                        break;
                    }
                }
                if (nextEdge == -1) break;

                edges[nextEdge].used = 1;
                int nxt = (edges[nextEdge].a == cur) ? edges[nextEdge].b : edges[nextEdge].a;
                prevEdge = nextEdge;
                cur = nxt;

                if (cur == s) {
                    faceVerts[faceCnt] = (int*)malloc(top * sizeof(int));
                    faceSz[faceCnt] = top;
                    for (int k = 0; k < top; ++k) faceVerts[faceCnt][k] = stack[k];
                    faceCnt++;
                    break;
                }
            }
        }
    }

    /* Build dual graph of rooms:
       each interior face is a node; outside is implicit.
       Two faces adjacent if they share an edge.
       A face adjacent to outside if one of its edges belongs to only that face.
    */
    int *boundary = (int*)calloc(faceCnt, sizeof(int));
    Vec *dual = (Vec*)calloc(faceCnt, sizeof(Vec));

    for (int i = 0; i < faceCnt; ++i) {
        for (int j = i + 1; j < faceCnt; ++j) {
            int common = 0;
            for (int a = 0; a < faceSz[i]; ++a) {
                int u1 = faceVerts[i][a];
                int v1 = faceVerts[i][(a + 1) % faceSz[i]];
                for (int b = 0; b < faceSz[j]; ++b) {
                    int u2 = faceVerts[j][b];
                    int v2 = faceVerts[j][(b + 1) % faceSz[j]];
                    if ((u1 == u2 && v1 == v2) || (u1 == v2 && v1 == u2)) {
                        common++;
                    }
                }
            }
            if (common > 0) {
                vec_push(&dual[i], j);
                vec_push(&dual[j], i);
            }
        }
    }

    for (int i = 0; i < faceCnt; ++i) {
        int sharedEdges = 0;
        for (int a = 0; a < faceSz[i]; ++a) {
            int u1 = faceVerts[i][a];
            int v1 = faceVerts[i][(a + 1) % faceSz[i]];
            int foundShared = 0;
            for (int j = 0; j < faceCnt && !foundShared; ++j) if (j != i) {
                for (int b = 0; b < faceSz[j]; ++b) {
                    int u2 = faceVerts[j][b];
                    int v2 = faceVerts[j][(b + 1) % faceSz[j]];
                    if ((u1 == u2 && v1 == v2) || (u1 == v2 && v1 == u2)) {
                        foundShared = 1;
                        break;
                    }
                }
            }
            if (foundShared) sharedEdges++;
        }
        if (sharedEdges < faceSz[i]) boundary[i] = 1;
    }

    if (faceCnt == 0) {
        printf("0\n");
        return 0;
    }

    /* Multi-source BFS from all boundary rooms.
       Distance = minimum number of walls/holes to outside.
    */
    int *dist = (int*)malloc(faceCnt * sizeof(int));
    int *q = (int*)malloc(faceCnt * sizeof(int));
    int head = 0, tail = 0;

    for (int i = 0; i < faceCnt; ++i) {
        if (boundary[i]) {
            dist[i] = 1;
            q[tail++] = i;
        } else {
            dist[i] = -1;
        }
    }

    while (head < tail) {
        int u = q[head++];
        for (int i = 0; i < dual[u].sz; ++i) {
            int v = dual[u].v[i];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q[tail++] = v;
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < faceCnt; ++i) {
        if (dist[i] > ans) ans = dist[i];
    }

    printf("%d\n", ans);
    return 0;
}

