#include <bits/stdc++.h>
using namespace std;

struct Point {
    long long x, y;
    Point() {}
    Point(long long _x, long long _y) : x(_x), y(_y) {}
    Point operator-(const Point& p) const { return Point(x - p.x, y - p.y); }
    long long cross(const Point& p) const { return x * p.y - y * p.x; }
    long long dot(const Point& p) const { return x * p.x + y * p.y; }
};

// Returns true if point p is inside convex polygon (vertices in ccw order)
// Works for strictly convex polygon. Uses winding number / cross product sign.
bool pointInConvexPolygon(const vector<Point>& poly, const Point& p) {
    int n = (int)poly.size();
    if (n == 0) return false;
    // Check if point is outside using cross product signs
    int sign = 0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        long long cross = (poly[j] - poly[i]).cross(p - poly[i]);
        if (cross != 0) {
            int s = (cross > 0) ? 1 : -1;
            if (sign == 0) sign = s;
            else if (sign != s) return false;
        }
    }
    return true;
}

// Returns orientation for ordering around reference point (for polar sort)
Point ref;
bool polarOrder(const Point& a, const Point& b) {
    long long cross = (a - ref).cross(b - ref);
    if (cross != 0) return cross > 0;
    return (a - ref).dot(a - ref) < (b - ref).dot(b - ref);
}

