#include <bits/stdc++.h>
using namespace std;

/*
We model the floor plan as a planar subdivision formed by line segments (walls).
Each wall has exactly one hole, so crossing one wall means passing through one hole.

The cat starts in some face (room), unknown to us, and will choose a route to the
outside minimizing the number of crossed walls. We must output the maximum, over all
faces, of this minimum number.

This is exactly the maximum graph distance from the outside face in the dual graph
of the arrangement:
- vertices of dual graph = faces
- an edge between two faces if they share a wall segment
- crossing one wall costs 1

So:
1. Build the planar graph from wall segments, splitting at intersections.
2. Enumerate all faces of the planar embedding.
3. For every primal edge, determine the two incident faces and connect them in dual.
4. BFS from the outer face in the dual.
5. Answer is the maximum distance.

Input format (standard for this classic problem):
n
x1 y1 x2 y2
...
xn yn xn yn
repeated until n = -1

Coordinates are integers. We use exact integer arithmetic for all topology tests.
*/

struct Point {
    long long x, y;
    bool operator<(const Point& other) const {
        if (x != other.x) return x < other.x;
        return y < other.y;
    }
    bool operator==(const Point& other) const {
        return x == other.x && y == other.y;
    }
};

struct Seg {
    Point a, b;
};

static long long cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static bool onSegment(const Point& a, const Point& b, const Point& p) {
    if (cross(a, b, p) != 0) return false;
    return min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) &&
           min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y);
}

static bool segmentsIntersect(const Seg& s1, const Seg& s2) {
    long long c1 = cross(s1.a, s1.b, s2.a);
    long long c2 = cross(s1.a, s1.b, s2.b);
    long long c3 = cross(s2.a, s2.b, s1.a);
    long long c4 = cross(s2.a, s2.b, s1.b);

    if ((c1 == 0 && onSegment(s1.a, s1.b, s2.a)) ||
        (c2 == 0 && onSegment(s1.a, s1.b, s2.b)) ||
        (c3 == 0 && onSegment(s2.a, s2.b, s1.a)) ||
        (c4 == 0 && onSegment(s2.a, s2.b, s1.b))) return true;

    return ((c1 > 0) != (c2 > 0)) && ((c3 > 0) != (c4 > 0));
}

// Assumes proper/endpoint intersection and integer-coordinate intersection point.
static Point lineIntersection(const Seg& s1, const Seg& s2) {
    // Solve with determinants using long double, then round.
    long double x1 = s1.a.x, y1 = s1.a.y;
    long double x2 = s1.b.x, y2 = s1.b.y;
    long double x3 = s2.a.x, y3 = s2.a.y;
    long double x4 = s2.b.x, y4 = s2.b.y;

    long double A1 = y2 - y1;
    long double B1 = x1 - x2;
    long double C1 = A1 * x1 + B1 * y1;

    long double A2 = y4 - y3;
    long double B2 = x3 - x4;
    long double C2 = A2 * x3 + B2 * y3;

    long double det = A1 * B2 - A2 * B1;
    long double x = (B2 * C1 - B1 * C2) / det;
    long double y = (A1 * C2 - A2 * C1) / det;

    return {(long long) llround(x), (long long) llround(y)};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int n;
        cin >> n;
        if (!cin) return 0;
        if (n == -1) break;

        vector<Seg> segs(n);
        for (int i = 0; i < n; ++i) {
            cin >> segs[i].a.x >> segs[i].a.y >> segs[i].b.x >> segs[i].b.y;
        }

        // Collect all vertices: endpoints and segment intersections.
        map<Point, int> pid;
        auto getPointId = [&](const Point& p) -> int {
            auto it = pid.find(p);
            if (it != pid.end()) return it->second;
            int id = (int)pid.size();
            pid[p] = id;
            return id;
        };

        vector<vector<Point>> ptsOnSeg(n);
        for (int i = 0; i < n; ++i) {
            ptsOnSeg[i].push_back(segs[i].a);
            ptsOnSeg[i].push_back(segs[i].b);
        }

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (!segmentsIntersect(segs[i], segs[j])) continue;

                // In this problem walls only meet at endpoints or cross properly.
                // We handle all integer-coordinate intersections.
                vector<Point> cand = {segs[i].a, segs[i].b, segs[j].a, segs[j].b};
                bool foundEndpoint = false;
                for (auto &p : cand) {
                    if (onSegment(segs[i].a, segs[i].b, p) && onSegment(segs[j].a, segs[j].b, p)) {
                        ptsOnSeg[i].push_back(p);
                        ptsOnSeg[j].push_back(p);
                        foundEndpoint = true;
                    }
                }
                if (!foundEndpoint) {
                    Point p = lineIntersection(segs[i], segs[j]);
                    ptsOnSeg[i].push_back(p);
                    ptsOnSeg[j].push_back(p);
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            sort(ptsOnSeg[i].begin(), ptsOnSeg[i].end(), [&](const Point& p1, const Point& p2) {
                if (segs[i].a.x != segs[i].b.x)
                    return (p1.x != p2.x) ? p1.x < p2.x : p1.y < p2.y;
                return (p1.y != p2.y) ? p1.y < p2.y : p1.x < p2.x;
            });
            ptsOnSeg[i].erase(unique(ptsOnSeg[i].begin(), ptsOnSeg[i].end()), ptsOnSeg[i].end());
        }

        vector<Point> points;
        points.reserve(pid.size());
        for (int i = 0; i < n; ++i) {
            for (auto &p : ptsOnSeg[i]) getPointId(p);
        }
        points.resize(pid.size());
        for (auto &kv : pid) points[kv.second] = kv.first;

        // Build planar graph edges after splitting.
        vector<vector<int>> adj(points.size());
        map<pair<int,int>, int> edgeId;
        vector<pair<int,int>> undirectedEdges;

        auto addEdge = [&](int u, int v) {
            if (u == v) return;
            if (u > v) swap(u, v);
            pair<int,int> e = {u, v};
            if (edgeId.count(e)) return;
            edgeId[e] = (int)undirectedEdges.size();
            undirectedEdges.push_back(e);
            adj[u].push_back(v);
            adj[v].push_back(u);
        };

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j + 1 < (int)ptsOnSeg[i].size(); ++j) {
                int u = getPointId(ptsOnSeg[i][j]);
                int v = getPointId(ptsOnSeg[i][j + 1]);
                addEdge(u, v);
            }
        }

        int V = points.size();

        // Sort adjacency by angle around each vertex.
        for (int u = 0; u < V; ++u) {
            sort(adj[u].begin(), adj[u].end(), [&](int v1, int v2) {
                long long dx1 = points[v1].x - points[u].x;
                long long dy1 = points[v1].y - points[u].y;
                long long dx2 = points[v2].x - points[u].x;
                long long dy2 = points[v2].y - points[u].y;
                long double a1 = atan2((long double)dy1, (long double)dx1);
                long double a2 = atan2((long double)dy2, (long double)dx2);
                return a1 < a2;
            });
        }

        // Traverse faces using directed edges.
        map<pair<int,int>, int> faceOfDir;
        vector<long double> faceArea;

        auto nextEdge = [&](int u, int v) -> pair<int,int> {
            // At vertex v, coming from u->v. To keep face on the left,
            // choose predecessor of u in cyclic order around v.
            auto &nbr = adj[v];
            int idx = 0;
            while (nbr[idx] != u) ++idx;
            int m = nbr.size();
            int w = nbr[(idx - 1 + m) % m];
            return {v, w};
        };

        int faceCnt = 0;
        for (auto &e : undirectedEdges) {
            int a = e.first, b = e.second;
            for (int t = 0; t < 2; ++t) {
                int u = (t == 0 ? a : b);
                int v = (t == 0 ? b : a);
                if (faceOfDir.count({u, v})) continue;

                vector<int> poly;
                int cu = u, cv = v;
                while (!faceOfDir.count({cu, cv})) {
                    faceOfDir[{cu, cv}] = faceCnt;
                    poly.push_back(cu);
                    auto ne = nextEdge(cu, cv);
                    cu = ne.first;
                    cv = ne.second;
                }

                long double area = 0;
                int m = poly.size();
                for (int i = 0; i < m; ++i) {
                    Point p = points[poly[i]];
                    Point q = points[poly[(i + 1) % m]];
                    area += (long double)p.x * q.y - (long double)p.y * q.x;
                }
                area /= 2.0;
                faceArea.push_back(area);
                faceCnt++;
            }
        }

        // Outer face is the one with negative area in this traversal convention
        // and with largest magnitude; more robustly choose the minimum area.
        int outer = 0;
        for (int i = 1; i < faceCnt; ++i) {
            if (faceArea[i] < faceArea[outer]) outer = i;
        }

        // Build dual graph.
        vector<vector<int>> dual(faceCnt);
        for (auto &e : undirectedEdges) {
            int u = e.first, v = e.second;
            int f1 = faceOfDir[{u, v}];
            int f2 = faceOfDir[{v, u}];
            if (f1 != f2) {
                dual[f1].push_back(f2);
                dual[f2].push_back(f1);
            }
        }

        // BFS from outer face.
        vector<int> dist(faceCnt, -1);
        queue<int> q;
        dist[outer] = 0;
        q.push(outer);

        while (!q.empty()) {
            int f = q.front(); q.pop();
            for (int g : dual[f]) {
                if (dist[g] == -1) {
                    dist[g] = dist[f] + 1;
                    q.push(g);
                }
            }
        }

        int ans = 0;
        for (int d : dist) ans = max(ans, d);
        cout << ans << "\n";
    }

    return 0;
}

