public class Main {
    // 2D point class with basic vector operations
    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
        Point sub(Point p) {
            return new Point(x - p.x, y - p.y);
        }
        double cross(Point p) {
            return x * p.y - y * p.x;
        }
        double dot(Point p) {
            return x * p.x + y * p.y;
        }
    }

    // Check if point p is inside convex polygon (vertices in ccw order)
    static boolean insideConvex(Point[] poly, Point p) {
        int n = poly.length;
        for (int i = 0; i < n; i++) {
            Point a = poly[i];
            Point b = poly[(i + 1) % n];
            if (b.sub(a).cross(p.sub(a)) < -1e-9) return false;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        Point[] outer = new Point[N];
        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().trim().split(" ");
            double x = Double.parseDouble(parts[0]);
            double y = Double.parseDouble(parts[1]);
            outer[i] = new Point(x, y);
        }

        int M = Integer.parseInt(br.readLine().trim());
        Point[] inner = new Point[M];
        for (int i = 0; i < M; i++) {
            String[] parts = br.readLine().trim().split(" ");
            double x = Double.parseDouble(parts[0]);
            double y = Double.parseDouble(parts[1]);
            inner[i] = new Point(x, y);
        }

        int H = Integer.parseInt(br.readLine().trim());
        Point[] holes = new Point[H];
        for (int i = 0; i < H; i++) {
            String[] parts = br.readLine().trim().split(" ");
            double x = Double.parseDouble(parts[0]);
            double y = Double.parseDouble(parts[1]);
            holes[i] = new Point(x, y);
        }

        // Build graph: nodes = holes + outside (node index H)
        int total = H + 1;
        List<Integer>[] graph = new ArrayList[total];
        for (int i = 0; i < total; i++) graph[i] = new ArrayList<>();

        // Connect holes if they can be directly reached without crossing walls
        for (int i = 0; i < H; i++) {
            for (int j = i + 1; j < H; j++) {
                if (canDirect(holes[i], holes[j], outer, inner)) {
                    graph[i].add(j);
                    graph[j].add(i);
                }
            }
        }

        // Connect holes to outside
        for (int i = 0; i < H; i++) {
            if (canReachOutside(holes[i], outer, inner)) {
                graph[i].add(H);
                graph[H].add(i);
            }
        }

        // BFS from outside to find max distance (in holes traversed)
        int[] dist = new int[total];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        dist[H] = 0;
        q.add(H);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }

        int maxDist = 0;
        for (int i = 0; i < H; i++) {
            if (dist[i] > maxDist) maxDist = dist[i];
        }
        // If some holes unreachable, they are inside inner polygon (impossible to exit)
        // But problem guarantees cat can always exit? We'll assume at least one path exists.
        System.out.println(maxDist);
    }

    // Check if segment a-b does NOT intersect any wall (outer or inner edges)
    static boolean canDirect(Point a, Point b, Point[] outer, Point[] inner) {
        // Check intersection with outer walls
        int n = outer.length;
        for (int i = 0; i < n; i++) {
            Point c = outer[i];
            Point d = outer[(i + 1) % n];
            if (segmentsIntersect(a, b, c, d)) return false;
        }
        // Check intersection with inner walls
        int m = inner.length;
        for (int i = 0; i < m; i++) {
            Point c = inner[i];
            Point d = inner[(i + 1) % m];
            if (segmentsIntersect(a, b, c, d)) return false;
        }
        return true;
    }

    // Check if point can reach outside: must be outside inner polygon and inside outer polygon,
    // and the segment from point to a far-away point does not intersect walls.
    static boolean canReachOutside(Point p, Point[] outer, Point[] inner) {
        // Must be inside outer polygon
        if (!insideConvex(outer, p)) return false;
        // Must be outside inner polygon
        if (insideConvex(inner, p)) return false;

        // Pick a far point outside outer polygon
        double farX = -1e9, farY = -1e9;
        Point far = new Point(farX, farY);

        // Check segment to far point does not intersect any wall
        int n = outer.length;
        for (int i = 0; i < n; i++) {
            Point c = outer[i];
            Point d = outer[(i + 1) % n];
            if (segmentsIntersect(p, far, c, d)) return false;
        }
        int m = inner.length;
        for (int i = 0; i < m; i++) {
            Point c = inner[i];
            Point d = inner[(i + 1) % m];
            if (segmentsIntersect(p, far, c, d)) return false;
        }
        return true;
    }

    // Segment intersection test (including endpoints properly)
    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        double d1 = cross(b.sub(a), c.sub(a));
        double d2 = cross(b.sub(a), d.sub(a));
        double d3 = cross(d.sub(c), a.sub(c));
        double d4 = cross(d.sub(c), b.sub(c));

        if (d1 * d2 < -1e-12 && d3 * d4 < -1e-12) return true;

        // Collinear cases: check if one endpoint lies on the other segment
        if (Math.abs(d1) < 1e-12 && onSegment(a, b, c)) return true;
        if (Math.abs(d2) < 1e-12 && onSegment(a, b, d)) return true;
        if (Math.abs(d3) < 1e-12 && onSegment(c, d, a)) return true;
        if (Math.abs(d4) < 1e-12 && onSegment(c, d, b)) return true;

        return false;
    }

    static double cross(Point a, Point b) {
        return a.x * b.y - a.y * b.x;
    }

    static boolean onSegment(Point a, Point b, Point p) {
        double minX = Math.min(a.x, b.x) - 1e-9;
        double maxX = Math.max(a.x, b.x) + 1e-9;
        double minY = Math.min(a.y, b.y) - 1e-9;
        double maxY = Math.max(a.y, b.y) + 1e-9;
        return p.x >= minX && p.x <= maxX && p.y >= minY && p.y <= maxY;
    }
}

