/*
 * The mansion is a planar subdivision inside one convex outer polygon.
 * Walls are straight segments between pillars; every wall has exactly one hole,
 * so moving from one face(room) to the adjacent face costs 1.
 *
 * We need the maximum, over all rooms, of the minimum number of walls crossed
 * to reach the outside face.
 *
 * In a planar graph, this is exactly shortest-path distance in the dual graph
 * from each bounded face to the outer face.
 *
 * Construction:
 * - Vertices: pillars.
 * - Edges: polygon boundary edges + internal walls.
 * - Embed graph by geometry.
 * - For every directed edge u->v, find the next directed edge along the face on
 *   its left by taking at vertex v the outgoing edge that is immediately before
 *   v->u in CCW order around v.
 * - Traversing these "next" pointers enumerates all faces.
 * - Build dual adjacency: each undirected edge separates one or two faces.
 *   Boundary edges have one bounded face and the outside face.
 * - BFS from outside face in dual graph; answer is maximum distance.
 *
 * Assumed input format:
 * n m
 * x1 y1
 * ...
 * xn yn
 * a1 b1
 * ...
 * am bm
 *
 * where the outer convex polygon is given by pillars 1..n in order around the
 * boundary, and m internal walls connect pairs of pillars.
 */
public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sgn;
        }
    }

    static class Pt {
        long x, y;
        Pt(long x, long y) { this.x = x; this.y = y; }
    }

    static class DirEdge {
        int from, to;
        int rev;
        int face = -1;
        int next = -1;
        int undirectedId;
        DirEdge(int from, int to, int undirectedId) {
            this.from = from;
            this.to = to;
            this.undirectedId = undirectedId;
        }
    }

    static Pt[] p;
    static ArrayList<Integer>[] out; // directed edge ids outgoing from vertex
    static ArrayList<DirEdge> de = new ArrayList<>();
    static int[] faceA, faceB; // for each undirected edge, adjacent faces
    static List<int[]> dualEdges = new ArrayList<>();

    static long cross(Pt a, Pt b, Pt c) {
        long x1 = b.x - a.x, y1 = b.y - a.y;
        long x2 = c.x - a.x, y2 = c.y - a.y;
        return x1 * y2 - y1 * x2;
    }

    static int addUndirectedEdge(int u, int v, int id) {
        int e1 = de.size();
        int e2 = e1 + 1;
        de.add(new DirEdge(u, v, id));
        de.add(new DirEdge(v, u, id));
        de.get(e1).rev = e2;
        de.get(e2).rev = e1;
        out[u].add(e1);
        out[v].add(e2);
        return e1;
    }

    static void sortAroundVertex(int v) {
        out[v].sort((e1, e2) -> {
            DirEdge a = de.get(e1), b = de.get(e2);
            Pt pa = p[a.to], pb = p[b.to], pv = p[v];
            long ax = pa.x - pv.x, ay = pa.y - pv.y;
            long bx = pb.x - pv.x, by = pb.y - pv.y;
            int ha = half(ax, ay);
            int hb = half(bx, by);
            if (ha != hb) return ha - hb;
            long cr = ax * by - ay * bx;
            if (cr > 0) return -1;
            if (cr < 0) return 1;
            return 0;
        });
    }

    static int half(long x, long y) {
        return (y > 0 || (y == 0 && x > 0)) ? 0 : 1;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = fs.nextInt();

        p = new Pt[n];
        for (int i = 0; i < n; i++) {
            p[i] = new Pt(fs.nextInt(), fs.nextInt());
        }

        out = new ArrayList[n];
        for (int i = 0; i < n; i++) out[i] = new ArrayList<>();

        int undirectedEdges = 0;

        // Outer polygon boundary
        for (int i = 0; i < n; i++) {
            int u = i;
            int v = (i + 1) % n;
            addUndirectedEdge(u, v, undirectedEdges++);
        }

        // Internal walls
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            addUndirectedEdge(u, v, undirectedEdges++);
        }

        faceA = new int[undirectedEdges];
        faceB = new int[undirectedEdges];
        Arrays.fill(faceA, -1);
        Arrays.fill(faceB, -1);

        // Sort outgoing edges around each vertex by angle CCW
        for (int i = 0; i < n; i++) sortAroundVertex(i);

        // Build next pointers for face traversal
        int D = de.size();
        for (int eid = 0; eid < D; eid++) {
            DirEdge e = de.get(eid);
            int v = e.to;
            ArrayList<Integer> list = out[v];
            int posRev = -1;
            for (int i = 0; i < list.size(); i++) {
                if (list.get(i) == e.rev) {
                    posRev = i;
                    break;
                }
            }
            int prev = (posRev - 1 + list.size()) % list.size();
            e.next = list.get(prev);
        }

        // Enumerate faces
        ArrayList<Long> faceArea2 = new ArrayList<>();
        int faceCnt = 0;
        for (int eid = 0; eid < D; eid++) {
            if (de.get(eid).face != -1) continue;
            int cur = eid;
            long area2 = 0;
            while (true) {
                DirEdge e = de.get(cur);
                e.face = faceCnt;
                Pt a = p[e.from], b = p[e.to];
                area2 += a.x * b.y - a.y * b.x;
                cur = e.next;
                if (cur == eid) break;
            }
            faceArea2.add(area2);
            faceCnt++;
        }

        // Outer face is the one with negative area under this traversal convention
        int outerFace = -1;
        for (int f = 0; f < faceCnt; f++) {
            if (faceArea2.get(f) < 0) {
                outerFace = f;
                break;
            }
        }

        // Map undirected edges to adjacent faces
        for (int eid = 0; eid < D; eid += 2) {
            int f1 = de.get(eid).face;
            int f2 = de.get(eid + 1).face;
            faceA[de.get(eid).undirectedId] = f1;
            faceB[de.get(eid).undirectedId] = f2;
        }

        ArrayList<Integer>[] dual = new ArrayList[faceCnt];
        for (int i = 0; i < faceCnt; i++) dual[i] = new ArrayList<>();

        for (int id = 0; id < undirectedEdges; id++) {
            int a = faceA[id], b = faceB[id];
            if (a != b) {
                dual[a].add(b);
                dual[b].add(a);
            }
        }

        int[] dist = new int[faceCnt];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[outerFace] = 0;
        q.add(outerFace);

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : dual[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }

        int ans = 0;
        for (int f = 0; f < faceCnt; f++) {
            if (f != outerFace) ans = Math.max(ans, dist[f]);
        }

        System.out.println(ans);
    }
}
